import { useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { supportedLanguages, defaultLanguage, stripLocalePrefix } from './config';
import { localizePath } from './paths';
import { SITE } from '../seo/meta';

/**
 * Injects <link rel="alternate" hreflang="..."> for every supported locale of
 * the current page, plus x-default, so search engines connect a page to its
 * translated counterparts instead of treating them as duplicate content.
 */
export function useHreflangTags(languages = null) {
  const { i18n } = useTranslation('edb');

  useEffect(() => {
    if (typeof document === 'undefined') return;
    const bare = stripLocalePrefix(window.location.pathname);

    // Prerendering bakes whatever this effect produces straight into the
    // static HTML; the client bundle then runs this same effect again on top
    // of that markup. Clear any tags already present (baked-in or from a
    // previous run) before adding the current set, so the two never stack.
    document.head.querySelectorAll('link[rel="alternate"][hreflang]').forEach((el) => el.remove());

    // A page that exists only in some languages (an article not translated yet) lists
    // only those: the others show the English text and are not alternates.
    const langs = languages ? supportedLanguages.filter((l) => languages.includes(l)) : supportedLanguages;
    const created = langs.map((lang) => {
      const link = document.createElement('link');
      link.rel = 'alternate';
      link.hreflang = lang;
      link.href = SITE + localizePath(bare, lang);
      document.head.appendChild(link);
      return link;
    });

    const xDefault = document.createElement('link');
    xDefault.rel = 'alternate';
    xDefault.hreflang = 'x-default';
    xDefault.href = SITE + localizePath(bare, defaultLanguage);
    document.head.appendChild(xDefault);
    created.push(xDefault);

    return () => created.forEach((el) => el.remove());
  }, [i18n.language, languages ? languages.join(',') : '']);
}
